// Corpus rows are generated by the Rust test from the existing Task 060/062 cases.
#include "service_codec.hpp"

#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <string_view>

namespace sc = service_codec;

namespace {

void require(bool condition, std::string_view context) {
    if (!condition) {
        std::cerr << context << '\n';
        std::exit(1);
    }
}

// Put the candidate in one slot only, so a failure can be attributed to its
// schema path. Schema order and compact spelling are independent of the codec.
std::string payload(bool ipv6, unsigned slot, std::string_view token) {
    const std::string_view dotted = R"("198.51.100.42")";
    const std::string_view colon = R"("fE80::aBcD")";
    const auto v4 = [&](unsigned index) { return !ipv6 && slot == index ? token : dotted; };
    const auto v6 = [&](unsigned index) { return ipv6 && slot == index ? token : colon; };
    std::string out = "{\"RequiredIPv4\":";
    out += v4(0);
    out += ",\"RequiredIPv6\":";
    out += v6(0);
    out += ",\"OptionalIPv4\":";
    out += v4(1);
    out += ",\"OptionalIPv6\":";
    out += v6(1);
    out += ",\"RepeatedIPv4\":[\"0.0.0.0\",";
    out += v4(2);
    out += "],\"RepeatedIPv6\":[\"::\",";
    out += v6(2);
    out += ipv6 ? "],\"Pick\":{\"IPv6\":" : "],\"Pick\":{\"IPv4\":";
    out += ipv6 ? v6(3) : v4(3);
    return out + "}}";
}

void check(bool ipv6, std::string_view token, bool valid, std::string_view reason) {
    const char* paths[][4] = {
        {"RequiredIPv4", "OptionalIPv4", "RepeatedIPv4[1]", "Pick.IPv4"},
        {"RequiredIPv6", "OptionalIPv6", "RepeatedIPv6[1]", "Pick.IPv6"},
    };
    for (unsigned slot = 0; slot < 4; ++slot) {
        const auto json = payload(ipv6, slot, token);
        const auto decoded = sc::decode_AddressPayload(json);
        require(decoded.ok() == valid, json);
        if (valid) {
            const auto encoded = sc::encode_AddressPayload(decoded.value());
            require(encoded && encoded.value() == json, json);
        } else {
            require(decoded.error().path == std::string("AddressPayload.") + paths[ipv6][slot],
                    decoded.error().path);
            require(decoded.error().message == reason, decoded.error().message);
        }
    }
}

std::size_t corpus(const char* file, bool ipv6) {
    std::ifstream stream(file);
    require(stream.is_open(), file);
    std::string line;
    std::size_t rows = 0;
    while (std::getline(stream, line)) {
        require(line.size() > 2 && line[1] == '\t' && (line[0] == '0' || line[0] == '1'), line);
        check(ipv6, std::string_view(line).substr(2), line[0] == '1',
              ipv6 ? "value rejected by the generated model's ColonType check"
                   : "value rejected by the generated model's DottedType check");
        ++rows;
    }
    require(stream.eof(), file);
    return rows;
}

}  // namespace

int main(int argc, char** argv) {
    require(argc == 3, "expected IPv4 and IPv6 corpus files");
    const auto ipv4 = corpus(argv[1], false);
    const auto ipv6 = corpus(argv[2], true);
    for (const bool colon : {false, true}) {
        check(colon, "42", false, "expected string, found number");
        check(colon, "null", false, "expected string, found null");
        check(colon, "[]", false, "expected string, found array");
        check(colon, "{}", false, "expected string, found object");
        check(colon, "true", false, "expected string, found boolean");
    }
    const auto malformed = sc::decode_AddressPayload(R"({"RequiredIPv6":"::1)");
    require(!malformed && malformed.error().path == "$" &&
            malformed.error().message.find("unterminated string") != std::string::npos,
            "malformed JSON must fail at $");
    const auto escaped = sc::decode_AddressPayload(payload(true, 0, R"("fE80\u003a:aBcD")"));
    require(escaped && escaped.value().requiredipv6.value() == "fE80::aBcD", "unescaped lexical value");
    const auto encoded = sc::encode_AddressPayload(escaped.value());
    require(encoded && encoded.value() == payload(true, 0, R"("fE80::aBcD")"), "escaped round trip");
    std::cout << "CPP_OMS_009A_ADDRESSES ipv4=" << ipv4 << " ipv6=" << ipv6 << '\n';
}